"""Banco de 50 ideias para os próximos dois meses (8 semanas a partir de 26/10/2026), em seis formatos misturados:
lista de 5, atualidade, a conta, história, por dentro e contra a corrente. Tom agressivo, para empresário.
Gera um JSON por ideia para a coleção `ideias` do Estúdio Escher.  uso: python ideias_50.py <pasta_saida>
"""
import json, os, sys

SEMANAS = ['26 out – 1 nov', '2 – 8 nov', '9 – 15 nov', '16 – 22 nov', '23 – 29 nov', '30 nov – 6 dez', '7 – 13 dez', '14 – 20 dez']
L5, AT, CT, HI, PD, CC = 'Lista de 5', 'Atualidade', 'A conta', 'História', 'Por dentro', 'Contra a corrente'
I = []
def idea(id, semana, formato, area, ano, titulo, gancho, porque, ancora, arco, prova, tecnico, humor, imagens, fecho, verificar='', top=False):
    I.append(dict(id=id, semana=semana, periodo=SEMANAS[semana - 1], formato=formato, area=area, ano=ano, titulo=titulo, gancho=gancho, porque=porque,
                  ancora=ancora, arco=arco, prova=prova, tecnico=tecnico, humor=humor, imagens=imagens, fecho=fecho, verificar=verificar, recomendada=top))

